window.kbPageData["views/entry/k-e85b8e4f09210b45"] = {"key":"entry/k-e85b8e4f09210b45","state":{"route":"entry/k-e85b8e4f09210b45"},"node":{"id":"k-e85b8e4f09210b45","mode":"k","title":"中华老字号复核与移出名录","type":"制度与规则","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":["中华老字号动态复核与移出名录的效力"],"qs":["江苏 2024 A类 行测#13"],"current":true,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"根据2023年《中华老字号示范创建管理办法》，商务部会同相关部门原则上每3年复核一次。品牌经复核已不符合条件的，由商务部商相关部门作出移出名录、收回标识使用权及牌匾的决定。","review":{"definition":"根据2023年《中华老字号示范创建管理办法》，商务部会同相关部门原则上每3年复核一次。品牌经复核已不符合条件的，由商务部商相关部门作出移出名录、收回标识使用权及牌匾的决定。","explanation":"移出名录直接影响品牌的中华老字号资格、标识使用权和牌匾。企业具备相应经营条件时仍可依法经营，因此本题参考答案将A项的“将退出市场”判错。C项可理解为通过复核本身不会扩大经营范围。第二十一条未设复核后不得扩大经营范围的特别限制，企业依法变更经营范围适用一般登记和许可规则。","references":[{"source":"web-1c0bb2999fb1767b","location":"第二十一条","quote":"移出中华老字号名录、收回中华老字号标识使用权及牌匾"},{"source":"web-d5f68264658c3746","location":"《国务院公报》2021年第25号，第十四条","quote":"市场主体的经营范围包括一般经营项目和许可经营项目"}],"evidence":"其仍然可以继续经营，只是不能再使用中华老字号标识。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 A类 行测#13":{"paper":"江苏 2024 A类 行测","n":13,"mod":"常识判断","src":["f8fec75f67d6d1ba5759.pdf",3],"asrc":["0126a1c8aceee632ea2b.pdf",5],"card":"282f254e54d473baf2288df6","links":[{"id":"k-e85b8e4f09210b45","role":"直接考查","why":"移出名录影响中华老字号标识使用权，品牌仍可依法继续经营。"}]}},"terms":{},"references":{"web-1c0bb2999fb1767b":{"name":"《中华老字号示范创建管理办法》（2023年）","url":"https://www.mofcom.gov.cn/zfxxgk/fdzdgknr/ztfl/gnmygl/art/2023/art_391e5837e27942b0a154aee3785b26d6.html"},"web-d5f68264658c3746":{"name":"《中华人民共和国市场主体登记管理条例》","url":"https://www.gov.cn/gbgl/332a752e6b70437c817e867f627514eb/files/b24690da8e324b49adce5c2f0b918977.pdf"}},"topics":[],"units":{"k-e85b8e4f09210b45":[["江苏 2024 A类 行测#13"]]}};
